package com.cpf.starter.smb;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;@AutoConfiguration @EnableConfigurationProperties(CpfSmbProperties.class) @ConditionalOnProperty(prefix="cpf.integration.smb",name="enabled",havingValue="true") public class CpfSmbAutoConfiguration {@Bean CpfSmbClient cpfSmbClient(CpfSmbProperties p){p.validate();return new CpfSmbClient(p);}}
